 type UnknownRecord = Record<string, unknown>;
 type ViewState = Record<string, boolean | number | string>;
 type ViewStateChange = (key: string, value: boolean | number | string) => void;

 function isRecord(value: unknown): value is UnknownRecord {
 	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 }

 function humanize(value: string): string {
 	return value
 		.replace(/[_-]+/g, " ")
 		.replace(/\b\w/g, (letter) => letter.toUpperCase());
 }

 function stringify(value: unknown): string {
 	try {
 		return JSON.stringify(value, null, 2);
 	} catch {
 		return String(value);
 	}
 }

 function compactValue(value: unknown): string {
 	if (value === null) return "null";
 	if (value === undefined) return "—";
 	if (typeof value === "string") return value;
 	if (typeof value === "number" || typeof value === "boolean")
 		return String(value);
 	return stringify(value);
 }

 const PersistentDetails: FC<{
 	summary: string;
 	stateKey: string;
 	viewState?: ViewState;
 	onViewStateChange?: ViewStateChange;
 	children: ReactNode;
 	className?: string;
 }> = ({
 	summary,
 	stateKey,
 	viewState = {},
 	onViewStateChange,
 	children,
 	className,
 }) => {
 	const restored = viewState[stateKey];
 	const [localOpen, setLocalOpen] = useState(restored === true);
+	useEffect(() => {
+		setLocalOpen(restored === true);
+	}, [restored]);
 	const open = typeof restored === "boolean" ? restored : localOpen;
 	return (
 		<div className={className}>
 			<button
 				type="button"
 				aria-expanded={open}
 				className="flex w-full cursor-pointer items-center gap-1.5 text-left font-medium"
 				onClick={() => {
 					const next = !open;
 					setLocalOpen(next);
 					onViewStateChange?.(stateKey, next);
 				}}
 			>
 				<span aria-hidden="true">{open ? "▾" : "▸"}</span>
 				<span>{summary}</span>
 			</button>
 			{open ? children : null}
